"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { useSession } from "next-auth/react";
import Link from "next/link";
import { useParams, useRouter } from "next/navigation";
import { ArrowLeft, Bot, Code2, Download, FileCode2, Laptop, Loader2, Maximize2, MessageSquarePlus, RefreshCcw, Smartphone, Tablet, WandSparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { api, type GeneratedFile, type GeneratedWebsite, type Project } from "@/lib/api";

type Device = "desktop" | "tablet" | "mobile";

const deviceClass: Record<Device, string> = {
  desktop: "w-full",
  tablet: "w-[780px] max-w-full",
  mobile: "w-[390px] max-w-full"
};

const deviceIcons = {
  desktop: Laptop,
  tablet: Tablet,
  mobile: Smartphone
};

export default function BuilderPage() {
  const params = useParams<{ projectId: string }>();
  const router = useRouter();
  const { status } = useSession({
    required: true,
    onUnauthenticated() {
      router.push("/login");
    }
  });
  const rawProjectId = params.projectId;
  const [projectId, setProjectId] = useState(rawProjectId);
  const [project, setProject] = useState<Project | null>(null);
  const [prompt, setPrompt] = useState("");
  const [chatText, setChatText] = useState("");
  const [device, setDevice] = useState<Device>("desktop");
  const [selectedFile, setSelectedFile] = useState("");
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [error, setError] = useState("");

  const website = project?.websites[0]?.generatedCode;
  const files = useMemo(() => website?.files ?? [], [website]);
  const activeFile = useMemo<GeneratedFile | undefined>(() => files.find((file) => file.path === selectedFile) ?? files[0], [files, selectedFile]);

  async function load(id: string) {
    setLoading(true);
    setError("");
    try {
      const loaded = await api.getProject(id);
      setProject(loaded);
      setPrompt(loaded.initialPrompt || "Create a modern restaurant website with menu, about, testimonials, and contact sections.");
      setSelectedFile(loaded.websites[0]?.generatedCode.files[0]?.path || "");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Unable to load project.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    async function bootstrap() {
      if (rawProjectId === "demo") {
        setLoading(true);
        const demo = await api.createProject({
          name: "Demo Restaurant",
          description: "A generated demo project for SiteCraft AI.",
          initialPrompt: "Create a modern restaurant website with a refined dining feel, menu highlights, reviews, and a contact section."
        });
        setProjectId(demo.id);
        router.replace(`/builder/${demo.id}`);
        await load(demo.id);
        return;
      }
      await load(rawProjectId);
    }

    void bootstrap();
  }, [rawProjectId, router]);

  if (status === "loading") {
    return (
      <main className="flex min-h-screen items-center justify-center bg-paper text-ink">
        <div className="flex items-center gap-2 text-sm text-ink/68">Loading session…</div>
      </main>
    );
  }

  async function generate(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setWorking(true);
    setError("");
    try {
      const result = await api.generate(projectId, prompt);
      setProject((current) =>
        current
          ? {
              ...current,
              status: "ready",
              websites: [
                {
                  id: `${projectId}-website`,
                  title: result.website.plan.siteName,
                  description: result.website.plan.siteDescription,
                  theme: result.website.plan.theme,
                  generatedCode: result.website,
                  version: current.websites[0]?.version ?? 1
                }
              ],
              messages: [
                ...current.messages,
                { id: crypto.randomUUID(), projectId, role: "user", content: prompt, createdAt: new Date().toISOString() },
                { id: crypto.randomUUID(), projectId, role: "assistant", content: `Generated ${result.website.plan.siteName}.`, createdAt: new Date().toISOString() }
              ]
            }
          : current
      );
      setSelectedFile(result.website.files[0]?.path || "");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Generation failed.");
    } finally {
      setWorking(false);
    }
  }

  async function revise(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!chatText.trim()) return;
    setWorking(true);
    setError("");
    const revision = chatText;
    setChatText("");
    try {
      const result = await api.revise(projectId, revision);
      setProject((current) =>
        current
          ? {
              ...current,
              websites: [
                {
                  ...(current.websites[0] ?? {
                    id: `${projectId}-website`,
                    title: result.website.plan.siteName,
                    description: result.website.plan.siteDescription,
                    theme: result.website.plan.theme,
                    version: 1
                  }),
                  generatedCode: result.website,
                  title: result.website.plan.siteName,
                  description: result.website.plan.siteDescription,
                  theme: result.website.plan.theme
                }
              ],
              messages: [
                ...current.messages,
                { id: crypto.randomUUID(), projectId, role: "user", content: revision, createdAt: new Date().toISOString() },
                { id: crypto.randomUUID(), projectId, role: "assistant", content: "Applied your requested change.", createdAt: new Date().toISOString() }
              ]
            }
          : current
      );
      setSelectedFile(result.website.files[0]?.path || "");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Revision failed.");
    } finally {
      setWorking(false);
    }
  }

  async function exportZip() {
    setWorking(true);
    setError("");
    try {
      const blob = await api.exportProject(projectId);
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = "generated-site.zip";
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Export failed.");
    } finally {
      setWorking(false);
    }
  }

  if (loading) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-ink text-white">
        <Loader2 className="mr-2 h-5 w-5 animate-spin" /> Loading builder
      </main>
    );
  }

  return (
    <main className="flex h-screen flex-col overflow-hidden bg-[#ede7dc] text-ink">
      <header className="flex h-14 shrink-0 items-center justify-between border-b border-line bg-white px-4">
        <div className="flex min-w-0 items-center gap-3">
          <Link href="/dashboard" className="inline-flex h-9 w-9 items-center justify-center rounded-md border border-line" title="Back to dashboard">
            <ArrowLeft className="h-4 w-4" />
          </Link>
          <div className="min-w-0">
            <p className="truncate text-sm font-black">{project?.name || "Untitled project"}</p>
            <p className="truncate text-xs text-ink/54">{project?.status || "draft"} · {website?.plan.siteName || "No website generated yet"}</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" className="h-9 px-3" onClick={() => void load(projectId)} title="Refresh">
            <RefreshCcw className="h-4 w-4" />
          </Button>
          <Button variant="accent" className="h-9 px-3" onClick={exportZip} disabled={!website || working}>
            <Download className="h-4 w-4" /> Download ZIP
          </Button>
        </div>
      </header>

      {error ? <div className="border-b border-red-200 bg-red-50 px-4 py-2 text-sm text-red-700">{error}</div> : null}

      <div className="grid min-h-0 flex-1 grid-cols-1 lg:grid-cols-[340px_minmax(0,1fr)_380px]">
        <aside className="panel-scroll min-h-0 resize-x overflow-auto border-r border-line bg-white p-4">
          <div className="flex items-center gap-2">
            <WandSparkles className="h-5 w-5 text-accent" />
            <h2 className="text-lg font-black tracking-normal">Prompt</h2>
          </div>
          <form onSubmit={generate} className="mt-4 space-y-3">
            <textarea
              className="min-h-44 w-full resize-y rounded-md border border-line bg-paper px-3 py-3 text-sm leading-6 outline-none focus:border-accent"
              value={prompt}
              onChange={(event) => setPrompt(event.target.value)}
              maxLength={3000}
              required
            />
            <Button type="submit" variant="accent" className="w-full" disabled={working}>
              {working ? <Loader2 className="h-4 w-4 animate-spin" /> : <Bot className="h-4 w-4" />} Generate website
            </Button>
          </form>

          <div className="mt-7 flex items-center gap-2">
            <MessageSquarePlus className="h-5 w-5 text-teal" />
            <h2 className="text-lg font-black tracking-normal">Edit chat</h2>
          </div>
          <div className="panel-scroll mt-3 max-h-64 space-y-3 overflow-auto">
            {(project?.messages ?? []).map((message) => (
              <div key={message.id} className={`rounded-lg border p-3 text-sm ${message.role === "user" ? "border-accent/30 bg-accent/8" : "border-line bg-paper"}`}>
                <p className="text-xs font-bold uppercase text-ink/45">{message.role}</p>
                <p className="mt-1 leading-6">{message.content}</p>
              </div>
            ))}
          </div>
          <form onSubmit={revise} className="mt-3 space-y-3">
            <textarea
              className="min-h-24 w-full resize-y rounded-md border border-line bg-paper px-3 py-3 text-sm leading-6 outline-none focus:border-teal"
              value={chatText}
              onChange={(event) => setChatText(event.target.value)}
              placeholder="Make the hero blue, add pricing, change the font..."
              disabled={!website}
            />
            <Button type="submit" variant="primary" className="w-full" disabled={!website || working}>
              Apply edit
            </Button>
          </form>
        </aside>

        <section className="flex min-h-0 flex-col overflow-hidden bg-[#d8d1c5]">
          <div className="flex h-12 shrink-0 items-center justify-between border-b border-line bg-white px-4">
            <div className="flex gap-1">
              {(["desktop", "tablet", "mobile"] as Device[]).map((mode) => {
                const Icon = deviceIcons[mode];
                return (
                  <button
                    key={mode}
                    className={`inline-flex h-8 w-9 items-center justify-center rounded-md ${device === mode ? "bg-ink text-white" : "hover:bg-black/5"}`}
                    onClick={() => setDevice(mode)}
                    title={mode}
                  >
                    <Icon className="h-4 w-4" />
                  </button>
                );
              })}
            </div>
            <button className="inline-flex h-8 w-8 items-center justify-center rounded-md hover:bg-black/5" title="Fullscreen">
              <Maximize2 className="h-4 w-4" />
            </button>
          </div>

          <div className="panel-scroll flex min-h-0 flex-1 justify-center overflow-auto p-5">
            {website ? <PreviewFrame website={website} className={deviceClass[device]} /> : <EmptyPreview />}
          </div>
        </section>

        <aside className="grid min-h-0 grid-rows-[auto_1fr] border-l border-line bg-white">
          <div className="border-b border-line p-4">
            <div className="flex items-center gap-2">
              <Code2 className="h-5 w-5 text-accent" />
              <h2 className="text-lg font-black tracking-normal">Generated code</h2>
            </div>
            {website?.qa ? (
              <div className="mt-3 rounded-md border border-line bg-paper p-3 text-sm">
                <p className="font-bold">QA score: {website.qa.score}/100</p>
                <p className="mt-1 text-ink/64">{website.qa.passed ? "Validation passed" : "Validation needs fixes"}</p>
              </div>
            ) : null}
          </div>
          <div className="grid min-h-0 grid-cols-[130px_1fr]">
            <div className="panel-scroll min-h-0 overflow-auto border-r border-line bg-paper p-2">
              {files.map((file) => (
                <button
                  key={file.path}
                  className={`mb-1 flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-xs ${activeFile?.path === file.path ? "bg-ink text-white" : "hover:bg-white"}`}
                  onClick={() => setSelectedFile(file.path)}
                  title={file.path}
                >
                  <FileCode2 className="h-3.5 w-3.5 shrink-0" />
                  <span className="truncate">{file.path}</span>
                </button>
              ))}
            </div>
            <pre className="panel-scroll min-h-0 overflow-auto bg-[#111315] p-4 text-xs leading-5 text-[#f7f3eb]">
              {activeFile?.content || "Generate a website to view files."}
            </pre>
          </div>
        </aside>
      </div>
    </main>
  );
}

function PreviewFrame({ website, className }: { website: GeneratedWebsite; className: string }) {
  return (
    <iframe
      title="Generated website preview"
      sandbox=""
      className={`${className} min-h-full rounded-lg border border-black/15 bg-white shadow-soft transition-all`}
      srcDoc={website.html}
    />
  );
}

function EmptyPreview() {
  return (
    <div className="flex h-full min-h-[420px] w-full max-w-2xl items-center justify-center rounded-lg border border-dashed border-ink/22 bg-white/60 p-8 text-center">
      <div>
        <WandSparkles className="mx-auto h-8 w-8 text-accent" />
        <h2 className="mt-4 text-2xl font-black tracking-normal">No preview yet</h2>
        <p className="mt-2 text-sm leading-6 text-ink/62">Enter a prompt and run the generation pipeline to render the website here.</p>
      </div>
    </div>
  );
}
